mapper.select:
SELECT id, joined_at, ended_at
FROM public.department_membership
WHERE department_id = #{departmentId}
  AND member_id = #{memberId}
  AND joined_at <= #{actualCheckInAt}
  AND (ended_at IS NULL OR #{actualCheckInAt} < ended_at)
ORDER BY joined_at DESC
LIMIT 1
FOR UPDATE

mapper.update:
UPDATE public.attendance_target
SET is_target = TRUE,
	membership_id = #{membershipId},
	added_source = 'MANUAL',
	changed_by_account_id = #{actorAccountId},
	changed_at = #{changedAt},
	change_reason = #{reason}
WHERE attendance_day_id = #{attendanceDayId}
  AND department_id = #{departmentId}
  AND member_id = #{memberId}
  AND NOT is_target

UPDATE public.attendance_record
SET note = #{note},
	updated_by_account_id = #{actorAccountId}
WHERE id = #{recordId}
